// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{})
}

// ServeMux is an abstraction of [http.ServeMux].
type ServeMux interface {
	HandleFunc(pattern string, handler func(http.ResponseWriter, *http.Request))
	http.Handler
}

type StdHTTPServerOptions struct {
	BaseURL          string
	BaseRouter       ServeMux
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, m ServeMux) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseRouter: m,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, m ServeMux, baseURL string) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseURL:    baseURL,
		BaseRouter: m,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options StdHTTPServerOptions) http.Handler {
	m := options.BaseRouter

	if m == nil {
		m = http.NewServeMux()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/me", wrapper.GetMe)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/tenant", wrapper.GetTenant)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api-keys", wrapper.ListAPIKeys)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api-keys", wrapper.CreateAPIKey)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/api-keys/{key_id}", wrapper.RevokeAPIKey)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/audit", wrapper.ListAuditEvents)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/plugins", wrapper.ListPlugins)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/plugins/{type}", wrapper.GetPlugin)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/tenants", wrapper.ListTenants)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/tenants/by-external-id/{external_id}", wrapper.DeleteTenant)
	m.HandleFunc(http.MethodPatch+" "+options.BaseURL+"/tenants/by-external-id/{external_id}", wrapper.PatchTenant)
	m.HandleFunc(http.MethodPut+" "+options.BaseURL+"/tenants/by-external-id/{external_id}", wrapper.UpsertTenant)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/tenants/{tenant_id}/members", wrapper.ListMembers)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/tenants/{tenant_id}/members/by-external-id/{user_external_id}", wrapper.RemoveMember)
	m.HandleFunc(http.MethodPut+" "+options.BaseURL+"/tenants/{tenant_id}/members/by-external-id/{user_external_id}", wrapper.UpsertMember)
	m.HandleFunc(http.MethodPatch+" "+options.BaseURL+"/users/by-external-id/{external_id}", wrapper.PatchUser)

	return m
}

