// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// ListAPIKeys List the tenant's API keys
	// (GET /api-keys)
	ListAPIKeys(ctx context.Context, request ListAPIKeysRequestObject) (ListAPIKeysResponseObject, error)
	// CreateAPIKey Create an API key
	// (POST /api-keys)
	CreateAPIKey(ctx context.Context, request CreateAPIKeyRequestObject) (CreateAPIKeyResponseObject, error)
	// RevokeAPIKey Revoke an API key
	// (DELETE /api-keys/{key_id})
	RevokeAPIKey(ctx context.Context, request RevokeAPIKeyRequestObject) (RevokeAPIKeyResponseObject, error)
	// ListAuditEvents Query the tenant's audit log
	// (GET /audit)
	ListAuditEvents(ctx context.Context, request ListAuditEventsRequestObject) (ListAuditEventsResponseObject, error)
	// GetMe The resolved caller
	// (GET /me)
	GetMe(ctx context.Context, request GetMeRequestObject) (GetMeResponseObject, error)
	// ListPlugins List the plugins this engine was built with
	// (GET /plugins)
	ListPlugins(ctx context.Context, request ListPluginsRequestObject) (ListPluginsResponseObject, error)
	// GetPlugin One plugin's manifest
	// (GET /plugins/{type})
	GetPlugin(ctx context.Context, request GetPluginRequestObject) (GetPluginResponseObject, error)
	// GetTenant The caller's tenant, with its limits
	// (GET /tenant)
	GetTenant(ctx context.Context, request GetTenantRequestObject) (GetTenantResponseObject, error)
	// ListTenants List tenants (platform only)
	// (GET /tenants)
	ListTenants(ctx context.Context, request ListTenantsRequestObject) (ListTenantsResponseObject, error)
	// DeleteTenant Soft-delete a tenant (platform only)
	// (DELETE /tenants/by-external-id/{external_id})
	DeleteTenant(ctx context.Context, request DeleteTenantRequestObject) (DeleteTenantResponseObject, error)
	// PatchTenant Change a tenant's name, status or limits (platform only)
	// (PATCH /tenants/by-external-id/{external_id})
	PatchTenant(ctx context.Context, request PatchTenantRequestObject) (PatchTenantResponseObject, error)
	// UpsertTenant Create or update a tenant by its external ID (platform only)
	// (PUT /tenants/by-external-id/{external_id})
	UpsertTenant(ctx context.Context, request UpsertTenantRequestObject) (UpsertTenantResponseObject, error)
	// ListMembers List a tenant's members (platform only)
	// (GET /tenants/{tenant_id}/members)
	ListMembers(ctx context.Context, request ListMembersRequestObject) (ListMembersResponseObject, error)
	// RemoveMember Remove a user from a tenant (platform only)
	// (DELETE /tenants/{tenant_id}/members/by-external-id/{user_external_id})
	RemoveMember(ctx context.Context, request RemoveMemberRequestObject) (RemoveMemberResponseObject, error)
	// UpsertMember Add a user to a tenant or change its role (platform only)
	// (PUT /tenants/{tenant_id}/members/by-external-id/{user_external_id})
	UpsertMember(ctx context.Context, request UpsertMemberRequestObject) (UpsertMemberResponseObject, error)
	// PatchUser Disable or rename a user everywhere (platform only)
	// (PATCH /users/by-external-id/{external_id})
	PatchUser(ctx context.Context, request PatchUserRequestObject) (PatchUserResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

